    for (const pending of [
      NOTHING_PENDING,
      deferring(NOTHING_PENDING, ["hero/arm"], undefined),
      deferring(NOTHING_PENDING, [], 2),
      deferring(NOTHING_PENDING, ["hero/arm"], 2),
